SourceCode.Declaration:
/// <summary>
/// Extension of <c>AssetTrans</c> to trigger the fixed asset acquisition posted business event.
/// </summary>
[ExtensionOf(tableStr(AssetTrans))]
final class AAXAssetTrans_Table_Extension
{
}

Method.Source:
/// <summary>
/// Triggers the fixed asset acquisition posted business event when an acquisition transaction is posted.
/// </summary>
void insert()
{
    next insert();

    if (this.TransType == AssetTransType::Acquisition)
    {
        if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(AAXFixedAssetAcquisitionPostedBusinessEvent)))
        {
            AAXFixedAssetAcquisitionPostedBusinessEvent::newFromAssetTrans(this).send();
        }
    }
}
